window.DEEP_NOTES=[
{from:11,to:18,title:'세 층을 분리해서 설명하기',rows:[['디렉토리 / inode','이름 → inode 번호 → 파일 속성·데이터 주소. 같은 inode를 참조하는 여러 이름도 가능하므로 이름과 파일 객체는 다른 층이다.'],['열린 파일 상태','open 한 번으로 만들어지는 상태다. 현재 offset과 O_APPEND 같은 파일 상태 플래그가 이 층에 있다.'],['프로세스 FD','프로세스가 사용하는 정수 인덱스다. 같은 번호라도 다른 프로세스의 테이블이면 서로 다른 참조일 수 있다.'],['예측 문제','한 파일을 두 번 open하면 inode는 공유할 수 있지만 열린 상태는 둘이다. dup이면 열린 상태가 하나이므로 offset이 함께 움직인다.']]},
{from:21,to:22,title:'사용자 공간과 커널 공간을 함께 추적하기',rows:[['허가 비트','USER·GROUP·OTHER 각각 3비트다. r=4, w=2, x=1로 더한다. 0640은 소유자 rw, 그룹 r, 나머지 없음이다.'],['권한과 접근 모드','파일 권한은 누가 무엇을 할 수 있는지, open 접근 모드는 이 fd로 어떤 I/O를 할지 정한다. 둘이 같은 값이나 같은 저장 위치는 아니다.'],['라이브러리 버퍼','fopen·printf 등의 stdio 계층은 사용자 공간 버퍼를 둘 수 있다. fflush와 커널 캐시의 fsync를 구분한다.'],['추적 질문','printf 호출 → 사용자 버퍼 → write → 커널 캐시 → 저장장치 중 지금까지 어느 단계가 끝났는가? 모든 호출이 곧바로 마지막 단계에 도달하지는 않는다.']]},
{from:23,to:24,title:'실패 처리는 반환값부터 시작한다',rows:[['확인 순서','1. 해당 함수의 실패 반환 규칙을 검사한다. 2. 실패라면 errno를 확인한다. 3. 복구·재시도·자원 정리·종료 중 대응을 고른다.'],['성공과 errno','성공했다고 errno가 0이 되지는 않는다. 지난 오류 값이 남을 수 있으므로 errno만으로 성공 여부를 결정하지 않는다.'],['메시지 함수','strerror(errno)는 문자열 주소를 돌려준다. perror("open")은 접두어와 현재 errno의 설명을 stderr로 출력하고 반환값이 없다.'],['함수별 규칙','open·read·write·lseek는 실패 -1이지만 성공 값의 의미는 다르다. open의 0은 유효한 fd, read의 0은 요청 조건에 따라 EOF, lseek의 0은 유효한 위치다.']]},
{from:25,to:30,title:'접근 모드 · 생성 조건 · 생성 권한',rows:[['접근 모드','O_RDONLY, O_WRONLY, O_RDWR 중 하나를 선택한다. O_RDONLY는 값이 0이므로 단순히 비트가 있는지 검사하는 방식에 주의한다.'],['O_CREAT와 mode','새 파일을 만들 수 있도록 요청하면 생성 권한 인수를 전달한다. 예: open("new.txt", O_WRONLY | O_CREAT, 0666). 기존 파일을 열기만 할 때 그 mode가 기존 권한을 바꾸지는 않는다.'],['O_TRUNC와 O_APPEND','쓰기 가능한 일반 파일의 O_TRUNC는 크기를 0으로 줄인다. O_APPEND는 매 write를 파일 끝에 배치한다. 기존 내용을 지울지, 뒤에 추가할지의 차이를 먼저 판단한다.'],['umask 계산','생성 권한 = 요청 mode & ~umask. 0666 & ~0022 = 0644. 실행 비트를 요청하지 않았으므로 umask가 실행 권한을 만들어 주지 않는다.'],['creat의 정확한 대응','creat(path, mode) ≡ open(path, O_WRONLY | O_CREAT | O_TRUNC, mode). 읽기 권한이 있는 파일을 만들었더라도 반환된 fd는 쓰기 전용이다.']]},
{from:31,to:36,title:'read 반환값으로 버퍼 유효 범위를 정하기',rows:[['n > 0','buf[0]부터 buf[n-1]까지만 새로 읽은 데이터다. offset은 실제 읽은 n만큼 증가한다. 요청 길이보다 작아도 실패가 아니다.'],['n == 0','일반 파일에서 양수 바이트를 요청했는데 EOF면 0이다. 요청 길이가 0인 호출도 0을 반환할 수 있으므로 호출 조건까지 본다.'],['n == -1','errno를 확인한다. EINTR는 읽기 전 중단, EAGAIN은 nonblocking에서 지금 읽을 데이터가 없을 때 등이다. 재시도 정책은 상황에 맞게 정한다.'],['문자열 출력','read는 널 종료를 자동 추가하지 않는다. char buf[101]; n=read(fd,buf,100); 뒤 n>=0일 때만 buf[n]=\'\0\';을 수행하면 %s 출력 범위를 만들 수 있다.'],['개행 수와 줄 수','파일 내용이 A\nB라면 개행은 1개다. 마지막 개행 없이 끝나는 B를 한 줄로 세려면 별도 정의와 처리가 필요하다. 원문 예제는 개행 문자를 센다.']]},
{from:37,to:39,title:'요청한 양과 완료한 양을 구분한다',rows:[['부분 쓰기','write가 10을 요청받고 4를 반환하면 앞 4바이트가 쓰였다. 다음에는 buf+4부터 남은 6바이트를 요청해야 한다. 처음부터 다시 쓰면 데이터가 중복될 수 있다.'],['반복 불변식','완료한 수 sent와 남은 수 total-sent를 유지한다. 양수 결과를 sent에 더하고, -1이면 errno에 따라 처리한다. 0처럼 진전이 없는 결과도 무한 반복하지 않도록 다룬다.'],['copy.c 추적','입력 read 결과 n을 출력 write 길이로 전달한다. 마지막 read가 37을 반환했다면 100이 아니라 37바이트만 내보낸다.'],['반영 단계','write 성공은 커널이 데이터를 받아들인 결과일 수 있다. 영속성 보장이 필요하면 이후 적절한 동기화 호출과 오류 처리까지 검토한다.']]},
{from:40,to:48,title:'offset 산술을 표로 그려 보기',rows:[['SEEK_SET','새 위치 = 0 + offset. 음수 인수를 주어 최종 위치가 음수가 되면 실패한다.'],['SEEK_CUR / SEEK_END','새 위치 = 현재 위치 + offset 또는 파일 크기 + offset. 음수 인수도 최종 위치가 유효하면 가능하다.'],['예시 계산','크기 8, 현재 위치 3에서 lseek(fd,-1,SEEK_CUR)는 2, lseek(fd,-2,SEEK_END)는 6이다. lseek는 버퍼에 데이터를 읽지 않는다.'],['끝 너머의 위치','크기 8에서 위치 11로 이동만 하면 크기는 8이다. 이후 Z를 1바이트 쓰면 크기 12가 되고 8~10 구간은 0으로 읽힐 수 있다.'],['별도 open의 추적','fd1과 fd2가 별도 open이면 fd1의 read(3) 뒤 위치는 (3,0)이다. 같은 inode라는 사실만으로 (3,3)이 되지 않는다.']]},
{from:49,to:54,title:'위치 · 크기 · 저장 완료는 서로 다른 상태다',rows:[['pread / pwrite','명시한 pos에서 I/O하고 공유 현재 offset을 유지한다. 이 교재의 위치 쓰기 실험은 O_APPEND를 끈 일반 파일 조건이다. Linux의 pwrite와 O_APPEND 조합은 별도 주의가 필요하다.'],['fsync / fdatasync','fsync는 파일 데이터와 관련 메타데이터, fdatasync는 데이터와 이후 검색에 필요한 메타데이터를 동기화한다. 파일 크기까지 무조건 제외하는 것은 아니다.'],['sync / O_SYNC','sync는 시스템 범위의 동기화와 연결되며 반환형은 void다. O_SYNC는 fd의 매 쓰기에 동기화 완료 조건을 부여한다.'],['truncate의 영향','크기를 줄이면 뒤 내용이 사라진다. 늘리면 확장 구간은 0으로 읽힌다. lseek와 달리 실제 파일 길이를 바꾸며 현재 offset은 바꾸지 않는다.'],['경계 예측','현재 offset 7에서 파일을 5로 줄인 뒤 일반 read를 하면 EOF에서 0을 받을 수 있다. offset이 자동으로 5로 내려갔다고 가정하지 않는다.']]},
{from:55,to:59,title:'복제되는 것은 파일 내용이 아니라 참조다',rows:[['dup의 번호 선택','프로세스에서 사용하지 않는 가장 작은 fd를 고른다. 0·1·2가 열려 있고 3만 추가로 열려 있다면 다음 dup은 4다. 닫힌 표준 fd가 있다면 결과가 더 작을 수 있다.'],['공유 상태','복제 fd는 같은 열린 파일 항목을 참조한다. 어느 쪽 read·write·lseek라도 같은 offset을 바꾼다. 파일 상태 플래그도 공유한다.'],['독립 fd 플래그','FD_CLOEXEC 같은 fd 자체의 플래그는 공유 offset과 다르다. dup의 새 fd에서 close-on-exec는 꺼진다. 모든 플래그를 한 종류로 뭉뚱그리지 않는다.'],['dup2의 원자성','대상 fd를 닫고 새 연결로 바꾸는 과정이 원자적으로 이루어진다. 유효한 oldfd와 newfd가 같으면 그대로 반환한다. oldfd가 유효하지 않으면 대상도 닫지 않는다.'],['stdout과 stdio','dup2는 fd 1의 연결을 바꾼다. printf의 사용자 버퍼에 남은 데이터까지 시점별로 구분하려면 재지정 전 fflush(stdout)를 고려한다.']]},
{from:60,to:67,title:'준비 상태와 데이터 읽기를 분리한다',rows:[['호출의 역할','select·poll은 어떤 fd가 I/O 가능한지 기다리고 결과를 알려 준다. 파일 내용을 buf에 옮기는 read 자체를 대신하는 함수가 아니다.'],['select의 n','최대 감시 fd + 1이다. fd 0과 7을 감시하면 8이다. 집합과 timeout은 호출 뒤 바뀔 수 있으므로 반복할 때 재구성한다.'],['poll의 nfds','배열 항목 개수다. 0과 7 두 항목이면 2다. events에는 원하는 비트를 넣고 결과는 revents에서 검사한다.'],['시간 단위','select의 timeval은 초·마이크로초, pselect와 ppoll의 timespec은 초·나노초, poll의 정수 timeout은 밀리초다. 5초는 poll 인수 5000이다.'],['대기 전후 조건','FIFO open이 먼저 기다릴 수 있다. stdout이 즉시 POLLOUT이면 입력 없이도 poll이 반환할 수 있다. timeout은 항상 소모하는 시간이 아니라 최대 대기 조건이다.']]},
{from:68,to:73,title:'인터페이스와 캐시와 영속성 연결하기',rows:[['VFS','응용 프로그램의 공통 호출을 여러 파일 시스템의 구현으로 연결한다. 공통 인터페이스는 모든 파일 시스템의 세부 특성이 같다는 뜻이 아니다.'],['지역성','인접 데이터를 접근하는 공간 지역성과 최근 데이터를 다시 쓰는 시간 지역성을 나눈다. 순차 배열 순회는 공간 지역성의 대표 사례다.'],['적중률','hit / 전체 참조다. 10회 중 8회 hit면 80%다. read-ahead는 미래 접근을 예상하여 미리 가져오는 전략이므로 실제 사용 패턴의 영향을 받는다.'],['dirty와 writeback','변경된 캐시가 저장장치에 아직 반영되지 않았으면 dirty다. writeback 전에 전원이 꺼질 때 최근 변경의 유실 위험을 설명할 수 있어야 한다.'],['역사와 개념','원문의 pdflush 명칭과 writeback의 일반 개념을 분리한다. 강의에서 역사적 구현을 어느 범위까지 요구했는지는 확인이 필요하다.']]}
];
